const listPendingSessionQueues = `-- name: ListPendingSessionQueues :many
WITH steer AS (
  SELECT 'steer'::text AS queue, q.item_id, q.bot_id, q.session_id, q.target_run_id AS run_id, q.payload, q.status, q.position, q.created_at
  FROM session_steer_queue q
  WHERE q.team_id = public.memoh_current_team_id() AND q.session_id = $1::uuid AND q.status = 'accepted'
  ORDER BY q.position, q.item_id
  LIMIT $2::bigint
), follow_up AS (
  SELECT 'follow_up'::text AS queue, q.item_id, q.bot_id, q.session_id, q.enqueued_during_run_id AS run_id, q.payload, q.status, q.position, q.created_at
  FROM session_follow_up_queue q
  WHERE q.team_id = public.memoh_current_team_id() AND q.session_id = $1::uuid AND q.status = 'accepted' AND q.assigned_run_id IS NULL
  ORDER BY q.position, q.item_id
  LIMIT $2::bigint
)
SELECT queue, item_id, bot_id, session_id, run_id, payload, status, position, created_at FROM steer
UNION ALL
SELECT queue, item_id, bot_id, session_id, run_id, payload, status, position, created_at FROM follow_up
`

type ListPendingSessionQueuesParams struct {
	TargetSessionID pgtype.UUID `json:"target_session_id"`
	MaxItems        int64       `json:"max_items"`
}

type ListPendingSessionQueuesRow struct {
	Queue     string             `json:"queue"`
	ItemID    pgtype.UUID        `json:"item_id"`
	BotID     pgtype.UUID        `json:"bot_id"`
	SessionID pgtype.UUID        `json:"session_id"`
	RunID     pgtype.UUID        `json:"run_id"`
	Payload   []byte             `json:"payload"`
	Status    string             `json:"status"`
	Position  int64              `json:"position"`
	CreatedAt pgtype.Timestamptz `json:"created_at"`
}

// One round trip for the UI list endpoint. Both queues are read in the same
// statement snapshot and bounded per queue; the queue column tells the caller
// which typed row shape to decode. Steer rows carry target_run_id in run_id,
// follow-up rows carry enqueued_during_run_id.
func (q *Queries) ListPendingSessionQueues(ctx context.Context, arg ListPendingSessionQueuesParams) ([]ListPendingSessionQueuesRow, error) {
	rows, err := q.db.Query(ctx, listPendingSessionQueues, arg.TargetSessionID, arg.MaxItems)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPendingSessionQueuesRow
	for rows.Next() {
		var i ListPendingSessionQueuesRow
		if err := rows.Scan(
			&i.Queue,
			&i.ItemID,
			&i.BotID,
			&i.SessionID,
			&i.RunID,
			&i.Payload,
			&i.Status,
			&i.Position,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

