const reorderAcceptedFollowUpQueue = `-- name: ReorderAcceptedFollowUpQueue :many
WITH locked_session AS MATERIALIZED (
  SELECT id
  FROM bot_sessions
  WHERE team_id = public.memoh_current_team_id()
    AND id = $1
    AND deleted_at IS NULL
  FOR UPDATE
), item AS MATERIALIZED (
  SELECT q.item_id, q.position
  FROM session_follow_up_queue q
  JOIN locked_session s ON s.id = q.session_id
  WHERE q.team_id = public.memoh_current_team_id()
    AND q.session_id = $1
    AND q.item_id = $2
    AND q.status = 'accepted'
    AND q.assigned_run_id IS NULL
), before_item AS MATERIALIZED (
  SELECT q.item_id, q.position
  FROM session_follow_up_queue q
  JOIN locked_session s ON s.id = q.session_id
  WHERE q.team_id = public.memoh_current_team_id()
    AND q.session_id = $1
    AND q.item_id = $3::uuid
    AND q.status = 'accepted'
    AND q.assigned_run_id IS NULL
), tail AS MATERIALIZED (
  SELECT COALESCE(MAX(q.position), 0) + 1 AS position
  FROM session_follow_up_queue q
  JOIN locked_session s ON s.id = q.session_id
  WHERE q.team_id = public.memoh_current_team_id()
    AND q.session_id = $1
    AND q.status = 'accepted'
    AND q.assigned_run_id IS NULL
), target AS MATERIALIZED (
  SELECT i.item_id, i.position AS current_position,
    CASE WHEN $3::uuid IS NULL THEN tail.position ELSE b.position END AS target_position
  FROM item i
  CROSS JOIN tail
  LEFT JOIN before_item b ON TRUE
  WHERE $3::uuid IS NULL OR b.item_id IS NOT NULL
), moved AS (
  UPDATE session_follow_up_queue q
  SET position = CASE
    WHEN q.item_id = target.item_id THEN target.target_position
    WHEN target.target_position < target.current_position
      AND q.position >= target.target_position AND q.position < target.current_position THEN q.position + 1
    WHEN target.target_position > target.current_position
      AND q.position > target.current_position AND q.position <= target.target_position THEN q.position - 1
    ELSE q.position
  END,
  updated_at = now()
  FROM target
  WHERE q.team_id = public.memoh_current_team_id()
    AND q.session_id = $1
    AND q.status = 'accepted'
    AND q.assigned_run_id IS NULL
    AND (
      q.item_id = target.item_id
      OR target.target_position < target.current_position
        AND q.position >= target.target_position AND q.position < target.current_position
      OR target.target_position > target.current_position
        AND q.position > target.current_position AND q.position <= target.target_position
    )
  RETURNING q.item_id, q.team_id, q.bot_id, q.session_id, q.enqueued_during_run_id, q.assigned_run_id, q.invocation_id, q.payload, q.status, q.position, q.claim_run_id, q.claim_owner_id, q.claim_fencing_token, q.created_at, q.updated_at
)
SELECT item_id, team_id, bot_id, session_id, enqueued_during_run_id, assigned_run_id, invocation_id, payload, status, position, claim_run_id, claim_owner_id, claim_fencing_token, created_at, updated_at FROM moved
UNION ALL
SELECT q.item_id, q.team_id, q.bot_id, q.session_id, q.enqueued_during_run_id, q.assigned_run_id, q.invocation_id, q.payload, q.status, q.position, q.claim_run_id, q.claim_owner_id, q.claim_fencing_token, q.created_at, q.updated_at
FROM session_follow_up_queue q
JOIN locked_session s ON s.id = q.session_id
WHERE q.team_id = public.memoh_current_team_id()
  AND q.session_id = $1
  AND q.status = 'accepted'
  AND q.assigned_run_id IS NULL
  AND EXISTS (SELECT 1 FROM target)
  AND NOT EXISTS (SELECT 1 FROM moved m WHERE m.item_id = q.item_id)
ORDER BY position, item_id
`

type ReorderAcceptedFollowUpQueueParams struct {
	SessionID    pgtype.UUID `json:"session_id"`
	ItemID       pgtype.UUID `json:"item_id"`
	BeforeItemID pgtype.UUID `json:"before_item_id"`
}

